contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // --- before values ---
        address thisAddr = address(this);
        uint balanceBefore = c.balances(thisAddr); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;

        // --- deciding call ---
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // --- after values ---
        uint balanceAfter = c.balances(thisAddr); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;

        assert(balanceAfter == balanceBefore + depositAmount && cBalanceAfter == cBalanceBefore + depositAmount);
    }

    receive() external payable {}
}

