// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        address thisAddr = address(this);
        uint256 balanceBefore;
        try c.balances(thisAddr) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        uint cBalanceBefore = address(c).balance;
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 balanceAfter;
        try c.balances(thisAddr) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        uint cBalanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore + depositAmount && cBalanceAfter == cBalanceBefore + depositAmount);
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
